-- S4-KAFKA-01 / ASSMS-36: persist outbound JobStatusChanged events in a transactional outbox
-- so broker outages do not cause status transitions to be silently lost.

USE jobdb;

CREATE TABLE IF NOT EXISTS job_status_outbox (
    id                CHAR(36)      NOT NULL,
    job_id            CHAR(36)      NOT NULL,
    event_type        VARCHAR(50)   NOT NULL,
    topic             VARCHAR(100)  NOT NULL,
    payload           JSON          NOT NULL,
    publish_attempts  INT           NOT NULL DEFAULT 0,
    last_error        VARCHAR(1000) NULL,
    created_at        TIMESTAMP(6)  NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    published_at      TIMESTAMP(6)  NULL,

    PRIMARY KEY (id),
    KEY ix_job_status_outbox_pending (published_at, created_at),
    CONSTRAINT fk_job_status_outbox_job FOREIGN KEY (job_id) REFERENCES jobs (id) ON DELETE RESTRICT
);
